// Zentrale Seiten-Registrierung fuer alle ALLRIS-Web-Seiten (Dashboard/Formulare).
// Neue Seite hinzufuegen = hier ein Eintrag mehr, alle bestehenden Seiten zeigen
// den Link automatisch (jede Seite ruft diesen Sub-Workflow bei jedem Aufruf auf).
const PAGES = [
  { key: 'status', label: 'Status-Uebersicht', path: '/webhook/allris-status' },
  { key: 'wahlkampf', label: 'Wahlkampf-Bildgenerator', path: '/webhook/wahlkampf-bild' }
];

const THEMES = {
  dark: { bg: '#5b8def', fg: '#0f1115', hoverBg: '#7ba3f5' },
  light: { bg: '#333333', fg: '#ffffff', hoverBg: '#555555' }
};

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

return $input.all().map(item => {
  const currentPage = item.json.currentPage;
  const theme = THEMES[item.json.theme] || THEMES.light;
  const links = PAGES
    .filter(p => p.key !== currentPage)
    .map(p => '<a class="allris-nav-btn" href="' + esc(p.path) + '">&rarr; ' + esc(p.label) + '</a>')
    .join(' ');
  const navHtml = links ? '<div class="allris-nav">' + links + '</div>' : '';
  const navCss = '.allris-nav{margin-bottom:16px;}' +
    '.allris-nav-btn{display:inline-block;background:' + theme.bg + ';color:' + theme.fg + ';text-decoration:none;font-weight:600;font-size:13px;padding:8px 16px;border-radius:6px;margin-right:8px;}' +
    '.allris-nav-btn:hover{background:' + theme.hoverBg + ';}';
  return { json: { navHtml: navHtml, navCss: navCss } };
});
